text:
:= by
  intro h
  cases h with k hk
  have h1 : n ^ 2 + 1 = 3 * k := hk
  have h2 : n ^ 2 = 3 * k - 1 := by rw [h1]
  have h3 : n ^ 2 ≡ -1 [MOD 3] := by rw [h2]; exact modEq_sub_modEq (modEq_of_divisible (3 * k)) (modEq_of_divisible 1)
  have h4 : n ^ 2 ≡ 2 [MOD 3] := by rw [h3]; exact modEq_neg_modEq (modEq_of_divisible 1)
  obtain h5 | h6 | h7 := modEq_cases_mod_3 n
  {
    exact contradiction h4 (by rw [h5]; exact modEq_pow)
  }
  {
    exact contradiction h4 (by rw [h6]; exact modEq_pow)
  }
  {
    exact contradiction h4 (by rw [h7]; exact modEq_pow)
  }
